solution.code:
class ConversationManager:
    def __init__(self, system_prompt: str):
        self.messages = [{"role": "system", "content": system_prompt}]

    def add_user(self, text: str):
        self.messages.append({"role": "user", "content": text})

    def add_assistant(self, text=None, tool_calls=None):
        msg = {"role": "assistant", "content": text}
        if tool_calls is not None:
            msg["tool_calls"] = tool_calls
        self.messages.append(msg)

    def add_tool_result(self, tool_call_id: str, content: str):
        prev = self.messages[-1] if self.messages else None
        if not prev or prev["role"] != "assistant" or "tool_calls" not in prev:
            raise ValueError("tool result must follow an assistant tool_call")
        self.messages.append({
            "role": "tool",
            "tool_call_id": tool_call_id,
            "content": content,
        })

def is_valid_transcript(messages: list[dict]) -> bool:
    if not messages or messages[0].get("role") != "system":
        return False
    for i, m in enumerate(messages):
        if m.get("role") == "tool":
            if i == 0:
                return False
            prev = messages[i - 1]
            if prev.get("role") != "assistant" or "tool_calls" not in prev:
                return False
    return True

if __name__ == "__main__":
    good = [
        {"role": "system", "content": "x"},
        {"role": "user", "content": "hi"},
        {"role": "assistant", "content": None, "tool_calls": [{"id": "c1"}]},
        {"role": "tool", "tool_call_id": "c1", "content": "ok"},
    ]
    bad = [{"role": "user", "content": "hi"}]
    print(is_valid_transcript(good), is_valid_transcript(bad))
